using System;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace RcsMap {
 public static class ShapeUiTests {
  static int checks;static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
  static void Check(bool value,string text){if(!value)throw new Exception("shape UI: "+text);checks++;}
  static T Field<T>(Editor editor,string name){return (T)typeof(Editor).GetField(name,Flags).GetValue(editor);}
  static object Call(Editor editor,string name,params object[] args){return typeof(Editor).GetMethod(name,Flags).Invoke(editor,args);}
  static MapDocument Doc(Editor editor){return Field<MapDocument>(editor,"doc");}
  static void Mouse(MapCanvas canvas,string method,Point point,MouseButtons button=MouseButtons.Left){typeof(MapCanvas).GetMethod(method,Flags).Invoke(canvas,new object[]{new MouseEventArgs(button,1,point.X,point.Y,0)});}
  static Point At(MapCanvas canvas,double x,double y){return Point.Round(canvas.ScreenPoint(x,y));}
  static bool Near(double a,double b,double epsilon=.001){return Math.Abs(a-b)<=epsilon;}
  static TerrainSurface Surface(Editor editor){return Doc(editor).Terrain.Surfaces[0];}
  static TerrainVertex Vertex(Editor editor,int index){return SurfaceOutline.Points(Surface(editor))[index];}
  static void Drag(MapCanvas c,Point from,Point to){Mouse(c,"OnMouseDown",from);Mouse(c,"OnMouseMove",to);Mouse(c,"OnMouseUp",to);}
  public static MapDocument Demo(){var d=new MapDocument{Version=6,Terrain=new TerrainMap{MaxSlope=30}};d.Settings.Width=7000;d.Settings.Height=5000;d.Settings.Radius=230;d.Settings.MaxSpeed=400;var platform=new TerrainSurface{Name="可编辑梯形平台",X=1400,Y=1400,Width=2600,Depth=1800,Z0=700,SpeedLimit=200};SurfaceOutline.ApplyPreset(platform,"trapezoid");var ramp=new TerrainSurface{Name="可旋转坡道",Kind=SurfaceKind.沿X直坡道,X=4500,Y=1400,Width=1800,Depth=1400,Z1=350,SpeedLimit=200};SurfaceOutline.ApplyPreset(ramp,"rectangle");d.Terrain.Surfaces.AddRange(new[]{platform,ramp});d.Points.Add(new Waypoint(600,600,0,150));d.Points.Add(new Waypoint(6200,600,0,150));d.Points[0].ArrivalActions.Add(new RouteAction{Kind=3,Name="保留的航点动作",Value=.1,Timeout=2});d.Obstacles.Add(new Obstacle(5000,3600,250,250));return d;}
  static MapDocument Rectangle(){var d=Demo();SurfaceOutline.ApplyPreset(d.Terrain.Surfaces[0],"rectangle");return d;}
  static void EditorWorkflow(string folder){string file=Path.Combine(Path.GetFullPath(folder),"shape-ui.rcsmap.json");File.WriteAllText(file,Rectangle().Json());using(var editor=new Editor()){editor.ShowInTaskbar=false;editor.Opacity=0;editor.Show();Application.DoEvents();editor.OpenRecovery(file);var canvas=Field<MapCanvas>(editor,"canvas");string id=Surface(editor).Id;Call(editor,"SetActiveSurface",id);Call(editor,"EditShape");canvas.Fit();Check(canvas.Mode==5,"shape entrance selects main-canvas mode");Check(Application.OpenForms.Count==1,"editing shape keeps one main window");string before=Doc(editor).Json();string pointId=Doc(editor).Points[0].Id,actionId=Doc(editor).Points[0].ArrivalActions[0].Id;double px=Doc(editor).Points[0].X,py=Doc(editor).Points[0].Y,ox=Doc(editor).Obstacles[0].X;
   var p=Vertex(editor,0);Drag(canvas,At(canvas,p.X,p.Y),At(canvas,p.X-137,p.Y-63));p=Vertex(editor,0);Check(Near(p.X,1300)&&Near(p.Y,1300),"vertex drag snaps absolute coordinates to grid");Check(Doc(editor).Version==6,"shape edits remain v6");Check(Doc(editor).Json()!=before,"actual mouse drag changes outline");Check(Doc(editor).Points[0].Id==pointId&&Doc(editor).Points[0].ArrivalActions[0].Id==actionId&&Doc(editor).Points[0].X==px&&Doc(editor).Points[0].Y==py&&Doc(editor).Obstacles[0].X==ox,"reshaping preserves existing objects and action IDs");string changed=Doc(editor).Json();Call(editor,"Undo");Check(Doc(editor).Json()==before,"whole vertex drag is one global undo");Call(editor,"Redo");Check(Doc(editor).Json()==changed,"global redo restores edited outline");Call(editor,"Undo");
   var points=SurfaceOutline.Points(Surface(editor));double y=(points[1].Y+points[2].Y)/2;Drag(canvas,At(canvas,points[1].X,y),At(canvas,points[1].X+200,y));var moved=SurfaceOutline.Points(Surface(editor));Check(Near(moved[1].X,4200)&&Near(moved[2].X,4200),"edge midpoint drag moves both edge vertices");Check(Near(moved[0].X,points[0].X)&&Near(moved[3].X,points[3].X),"edge drag leaves other vertices unchanged");Call(editor,"Undo");Check(Doc(editor).Json()==before,"edge drag has one global undo");
   p=Vertex(editor,0);Mouse(canvas,"OnMouseDown",At(canvas,p.X,p.Y));Mouse(canvas,"OnMouseMove",At(canvas,p.X-200,p.Y-200));Check(Doc(editor).Json()!=before,"live vertex preview applied");Mouse(canvas,"OnMouseDown",At(canvas,0,0),MouseButtons.Right);Check(Doc(editor).Json()==before,"right click restores mouse-down shape snapshot");
   p=Vertex(editor,0);Mouse(canvas,"OnMouseDown",At(canvas,p.X,p.Y));Mouse(canvas,"OnMouseMove",At(canvas,p.X-100,p.Y-100));Call(editor,"KeysDown",editor,new KeyEventArgs(Keys.Escape));Check(Doc(editor).Json()==before,"Escape restores shape snapshot without closing editor");
   p=Vertex(editor,0);Mouse(canvas,"OnMouseDown",At(canvas,p.X,p.Y));Mouse(canvas,"OnMouseMove",At(canvas,p.X-100,p.Y-100));canvas.Capture=false;Check(Doc(editor).Json()==before&&!canvas.IsEditingShape,"capture loss cancels shape drag");
   p=Vertex(editor,0);Drag(canvas,At(canvas,p.X,p.Y),At(canvas,3300,2800));Check(Doc(editor).Json()==before,"concave vertex candidate rejected atomically");Check(!canvas.IsInteracting,"invalid candidate does not leave input capture active");
   Check(canvas.ApplyShapePreset("triangle"),"triangle preset applies through canvas transaction");Check(SurfaceOutline.Points(Surface(editor)).Count==3,"triangle has three actual vertices");Check(canvas.InsertShapeVertex(),"insert adds point on edge");Check(SurfaceOutline.Points(Surface(editor)).Count==4,"insert preserves collinear midpoint vertex");Check(canvas.DeleteShapeVertex(),"delete selected inserted point");Check(SurfaceOutline.Points(Surface(editor)).Count==3,"delete returns triangle");Check(!canvas.DeleteShapeVertex(),"triangle minimum vertex count enforced");
   var triangle=SurfaceOutline.Points(Surface(editor));Check(canvas.RotateShape(90),"90-degree rotation applies");Check(canvas.RotateShape(-90),"inverse rotation applies");var restored=SurfaceOutline.Points(Surface(editor));Check(triangle.Zip(restored,(a,b)=>Near(a.X,b.X)&&Near(a.Y,b.Y)).All(x=>x),"rotation preserves shape instead of rotating only AABB");Check(canvas.ApplyShapePreset("ellipse")&&SurfaceOutline.Points(Surface(editor)).Count==16,"ellipse is explicit 16-vertex approximation");
   Call(editor,"SetActiveSurface",Doc(editor).Terrain.Surfaces[1].Id);Check(canvas.RotateShape(15),"ramp rotation applies");var ramp=Doc(editor).Terrain.Surfaces[1];Check(ramp.Kind==SurfaceKind.任意方向直坡道&&Near(ramp.RampDirectionDeg.Value,15),"ramp height axis rotates with outline");Call(editor,"Undo");Check(Doc(editor).Terrain.Surfaces[1].Kind==SurfaceKind.沿X直坡道,"rotation undo restores original ramp kind");
   var profile=Field<TerrainCanvas>(editor,"profileView");var three=Field<TerrainCanvas>(editor,"threeView");Check(Object.ReferenceEquals(profile.Document,Doc(editor))&&Object.ReferenceEquals(three.Document,Doc(editor)),"shape history rebinds both other views");
   string saved=Path.Combine(Path.GetFullPath(folder),"edited-shape.rcsmap.json");typeof(Editor).GetField("filename",Flags).SetValue(editor,saved);Check((bool)Call(editor,"Save",false),"v6 shape draft saves through main-window command");Check(MapDocument.Parse(File.ReadAllText(saved)).Json()==Doc(editor).Json(),"v6 shape roundtrip exact");
   editor.Size=new Size(1120,800);Application.DoEvents();canvas.Fit();Call(editor,"SetActiveSurface",id);Call(editor,"EditShape");Check(Field<Button>(editor,"shapeEditButton").Visible&&Field<Button>(editor,"shapeMenuButton").Visible,"shape controls exposed at minimum window size");Check(canvas.Width>=440&&canvas.Height>=380,"shape editing canvas remains usable at minimum size");var shapeButton=Field<Button>(editor,"shapeEditButton");Check(shapeButton.Bottom<=shapeButton.Parent.ClientSize.Height&&Field<Button>(editor,"shapeMenuButton").Bottom<=shapeButton.Parent.ClientSize.Height,"shape entrances are not clipped by wrapped toolbar");using(var bitmap=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(bitmap,new Rectangle(0,0,editor.Width,editor.Height));bitmap.Save(Path.Combine(folder,"shape-minimum.png"));}typeof(Editor).GetField("savedJson",Flags).SetValue(editor,Doc(editor).Json());editor.Close();
  }}
  sealed class ProbeCanvas:MapCanvas {public bool Bypass;protected override bool ShapeBypassSnap {get{return Bypass;}}}
  static void ModifiersAndPaint(string folder){using(var form=new Form{ShowInTaskbar=false,Opacity=0,Size=new Size(1100,760)})using(var canvas=new ProbeCanvas{Document=Rectangle(),Mode=5}){form.Controls.Add(canvas);form.Show();Application.DoEvents();canvas.ActiveSurfaceId=canvas.Document.Terrain.Surfaces[0].Id;canvas.Fit();string start=canvas.Document.Json();canvas.BeginChange=()=>{start=canvas.Document.Json();};canvas.CancelChange=()=>{canvas.Document=MapDocument.Parse(start);};canvas.EndChange=()=>{};var s=canvas.Document.Terrain.Surfaces[0];var p=SurfaceOutline.Points(s)[0];canvas.Bypass=true;Drag(canvas,At(canvas,p.X,p.Y),At(canvas,1263,1337));p=SurfaceOutline.Points(s)[0];Check(Math.Abs(p.X/100-Math.Round(p.X/100))>.01||Math.Abs(p.Y/100-Math.Round(p.Y/100))>.01,"Shift branch bypasses grid snap");Check(Math.Abs(p.X-1263)<15&&Math.Abs(p.Y-1337)<15,"free vertex drag follows pointer world coordinate");
   canvas.Document=Rectangle();canvas.ActiveSurfaceId=canvas.Document.Terrain.Surfaces[0].Id;s=canvas.Document.Terrain.Surfaces[0];canvas.Bypass=false;var h=canvas.ShapeRotationHandle();var w=canvas.WorldPoint(Point.Round(h));double cx=s.X+s.Width/2,cy=s.Y+s.Depth/2,a=30*Math.PI/180,dx=w.X-cx,dy=w.Y-cy;var to=At(canvas,cx+dx*Math.Cos(a)-dy*Math.Sin(a),cy+dx*Math.Sin(a)+dy*Math.Cos(a));Drag(canvas,Point.Round(h),to);var poly=SurfaceOutline.Points(s);double angle=Math.Atan2(poly[1].Y-poly[0].Y,poly[1].X-poly[0].X)*180/Math.PI;Check(Near(angle,30,.001),"actual rotation handle snaps angle to15-degree increments");
   canvas.Document=Rectangle();canvas.ActiveSurfaceId=canvas.Document.Terrain.Surfaces[0].Id;Check(canvas.ApplyShapePreset("triangle"),"polygon paint fixture");canvas.Mode=0;var actual=canvas.Document;var baseline=actual.Clone();baseline.Terrain.Surfaces.RemoveAt(0);using(var one=new Bitmap(canvas.Width,canvas.Height))using(var two=new Bitmap(canvas.Width,canvas.Height))using(var g=Graphics.FromImage(one))using(var g2=Graphics.FromImage(two)){canvas.Draw(g,new Rectangle(0,0,canvas.Width,canvas.Height));canvas.Document=baseline;canvas.Draw(g2,new Rectangle(0,0,canvas.Width,canvas.Height));canvas.Document=actual;var outside=At(canvas,1530,2700);var inside=At(canvas,2700,1900);Check(one.GetPixel(outside.X,outside.Y).ToArgb()==two.GetPixel(outside.X,outside.Y).ToArgb(),"outside-polygon area remains clear inside AABB");Check(one.GetPixel(inside.X,inside.Y).ToArgb()!=two.GetPixel(inside.X,inside.Y).ToArgb(),"inside-polygon area actually filled");one.Save(Path.Combine(folder,"shape-polygon.png"));}
   canvas.Mode=5;var before=canvas.Document.Json();var vertex=SurfaceOutline.Points(canvas.Document.Terrain.Surfaces[0])[0];Mouse(canvas,"OnMouseDown",At(canvas,vertex.X,vertex.Y));Mouse(canvas,"OnMouseMove",At(canvas,vertex.X-100,vertex.Y-100));canvas.Width+=10;Check(canvas.Document.Json()==before&&!canvas.IsEditingShape,"resize cancels active shape drag");form.Close();
  }}
  public static void Run(string folder){Directory.CreateDirectory(folder);EditorWorkflow(folder);ModifiersAndPaint(folder);File.WriteAllText(Path.Combine(folder,"shape-ui-selftest.txt"),"PASS "+checks+" shape UI checks\n");Console.WriteLine("PASS "+checks+" shape UI checks");}
 }
}
